-- 573: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 3 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_573_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_573_guard;
INSERT INTO _migration_573_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_005' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" When Efua says "but so is the time we lose fetching it", she means that' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the hours spent fetching water are as precious as water itself","B. fetching water is a pleasant pastime","C. water is far more valuable than time","D. time passes quickly at the borehole"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The parallel "so is" gives the lost time the same worth as water: both are "life". Efua does not call fetching pleasant or time cheap. Therefore the correct answer is A: the hours spent fetching water are as precious as water itself.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_005' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_573_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_007' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Zebilla Senior High reached the regional debating finals. Coach Adongo insisted that facts must be clothed in courtesy. On the day, their opponents spoke louder, but Zebilla spoke better: every claim was supported, every rebuttal polite. The verdict was unanimous, and the trophy rode home on the captain''s knees like a baby." Coach Adongo''s rule that "facts must be clothed in courtesy" means that' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. debaters must dress well for contests","B. politeness can replace facts","C. arguments should be sound and expressed politely","D. facts should be hidden from opponents"]' AND q.correct_answer IS 'C' AND q.explanation IS 'To clothe facts in courtesy is to dress sound arguments in polite language, as the team did. Dress, substitution and concealment miss the figurative sense. Therefore the correct answer is C: arguments should be sound and expressed politely.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Interpret' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_007' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_573_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_008' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "Zebilla Senior High reached the regional debating finals. Coach Adongo insisted that facts must be clothed in courtesy. On the day, their opponents spoke louder, but Zebilla spoke better: every claim was supported, every rebuttal polite. The verdict was unanimous, and the trophy rode home on the captain''s knees like a baby." Zebilla won the finals mainly because' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. their opponents failed to turn up","B. they spoke louder than their opponents","C. the judges came from Zebilla","D. their claims were supported and their rebuttals polite"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Their opponents "spoke louder, but Zebilla spoke better", and the verdict was unanimous; no absence, greater volume or local judges is mentioned. Therefore the correct answer is D: their claims were supported and their rebuttals polite.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_008' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_573_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_025' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Choose the best summary of the following. — "The headmaster closed the school at noon. A leaking gas cylinder had been discovered near the kitchen, and the fire service advised an immediate evacuation."' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The school was closed at noon because a leaking gas cylinder made evacuation necessary.","B. The fire service closed the school because the kitchen caught fire.","C. The headmaster discovered the gas cylinder after closing the school.","D. The school was evacuated because the fire service leaked gas."]' AND q.correct_answer IS 'A' AND q.explanation IS 'A correct summary keeps the cause chain: the leaking cylinder led to the closure and the advised evacuation; each wrong option reverses the sequence, invents a fire or blames the fire service. Therefore the correct answer is A: The school was closed at noon because a leaking gas cylinder made evacuation necessary..' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_025' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_005', 'topic_wassce_p2_eng_cmp', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" When Efua says "but so is the time we lose fetching it", she means that', 'multiple_choice', NULL, '["A. the hours spent fetching water are as precious as water itself","B. fetching water is a pleasant pastime","C. water is far more valuable than time","D. time passes quickly at the borehole"]', 'A', 'The parallel "so is" gives the lost time the same worth as water: both are "life". Efua does not call fetching pleasant or time cheap. Therefore the correct answer is A: the hours spent fetching water are as precious as water itself.', 'medium', '3', '1', '60', NULL, NULL, '1', NULL, NULL, 'Interpret', 'AO2', NULL, NULL, NULL);
